204	// UseTimezone converts last login date to the given timezone.
205	func (u *User) UseTimezone(tz string) {
206		if u.LastLoginAt != nil {
207			*u.LastLoginAt = timezone.Convert(tz, *u.LastLoginAt)
208		}
